/**
 * Bench Submit: Load pre-generated proofs, reset chain state, submit relay batches, measure TPS.
 *
 * This is the fast, repeatable part of the benchmark. It loads proofs from bench-proofs.json
 * (generated by bench-setup.ts), calls debugResetBenchState to clear nullifiers and restore
 * the merkle root, then submits all relay batches.
 *
 * Usage:
 *   npx hardhat run scripts/bench-submit.ts --network localhost
 */
import { ethers } from 'hardhat';
import * as fs from 'fs';
import * as path from 'path';
import { arrayToHexString, hexStringToArray } from '../helpers/global/bytes';
import { PublicInputs } from '../helpers/logic/transaction';

// ============ Internal constants ============
const GAS_LIMIT_PER_RELAY = 30000000;

// ============ Deserialization helpers ============

function fromHex(hex: string): Uint8Array {
  return hexStringToArray(hex);
}

function deserializePublicInputs(s: any): PublicInputs {
  return {
    proof: {
      a: { x: BigInt(s.proof.a.x), y: BigInt(s.proof.a.y) },
      b: {
        x: [BigInt(s.proof.b.x[0]), BigInt(s.proof.b.x[1])],
        y: [BigInt(s.proof.b.y[0]), BigInt(s.proof.b.y[1])],
      },
      c: { x: BigInt(s.proof.c.x), y: BigInt(s.proof.c.y) },
    },
    merkleRoot: fromHex(s.merkleRoot),
    rootIndex: s.rootIndex,
    nullifiers: s.nullifiers.map(fromHex),
    commitments: s.commitments.map(fromHex),
    boundParams: {
      minGasPrice: BigInt(s.boundParams.minGasPrice),
      unshield: s.boundParams.unshield,
      chainID: BigInt(s.boundParams.chainID),
      adaptContract: s.boundParams.adaptContract,
      adaptParams: fromHex(s.boundParams.adaptParams),
      commitmentCiphertext: s.boundParams.commitmentCiphertext.map((cc: any) => ({
        ciphertext: cc.ciphertext.map(fromHex) as [Uint8Array, Uint8Array, Uint8Array, Uint8Array],
        blindedSenderViewingKey: fromHex(cc.blindedSenderViewingKey),
        blindedReceiverViewingKey: fromHex(cc.blindedReceiverViewingKey),
        annotationData: fromHex(cc.annotationData),
        memo: fromHex(cc.memo),
      })),
    },
    unshieldPreimage: {
      npk: fromHex(s.unshieldPreimage.npk),
      token: {
        tokenType: s.unshieldPreimage.token.tokenType,
        tokenAddress: s.unshieldPreimage.token.tokenAddress,
        tokenSubID: BigInt(s.unshieldPreimage.token.tokenSubID),
      },
      value: BigInt(s.unshieldPreimage.value),
    },
  };
}

// ============ Main ============

async function main() {
  // ========== Load proofs ==========
  const proofsPath = path.join(__dirname, '../bench-proofs.json');
  if (!fs.existsSync(proofsPath)) {
    throw new Error('bench-proofs.json not found. Run ./1-setup.sh first.');
  }

  console.log('Loading bench-proofs.json...');
  const loadStart = Date.now();
  const benchProofs = JSON.parse(fs.readFileSync(proofsPath, 'utf-8'));
  const loadMs = Date.now() - loadStart;

  const { config, rootIndex, root, nullifiers, batches, proofStats, setupStats } = benchProofs;

  console.log('============================================');
  console.log('  Privacy Transact Benchmark (Submit)');
  console.log('============================================');
  console.log(`  Wallets: ${config.wallets}`);
  console.log(`  Total TXs: ${config.totalTxs}`);
  console.log(`  TXs per relay: ${config.txsPerRelay}`);
  console.log(`  Circuit: ${config.inputsPerTx}-in / ${config.outputsPerTx}-out`);
  console.log(`  Relay batches: ${batches.length}`);
  console.log(`  Nullifiers to reset: ${nullifiers.length}`);
  console.log(`  Proofs loaded in ${loadMs}ms`);
  console.log('============================================\n');

  // ========== Load deployment config ==========
  const configPath = path.join(__dirname, '../deployments.json');
  if (!fs.existsSync(configPath)) {
    throw new Error('deployments.json not found. Run ./1-setup.sh first.');
  }
  const deployConfig = JSON.parse(fs.readFileSync(configPath, 'utf-8'));

  // ========== Connect contracts ==========
  const RailgunSmartWallet = await ethers.getContractFactory('RailgunSmartWalletStub', {
    libraries: { PoseidonT3: deployConfig.poseidonT3, PoseidonT4: deployConfig.poseidonT4 },
  });
  const railgun = RailgunSmartWallet.attach(deployConfig.proxy);
  const RelayAdapt = await ethers.getContractFactory('RelayAdapt');
  const relayAdapt = RelayAdapt.attach(deployConfig.relayAdaptProxy);

  // ========== Get accounts ==========
  const signers = await ethers.getSigners();
  const deployer = signers[0];
  const broadcaster = signers[1];

  // Fund broadcaster if needed
  const MIN_ETH = ethers.utils.parseEther('1');
  const broadcasterBalance = await broadcaster.getBalance();
  if (broadcasterBalance.lt(MIN_ETH)) {
    console.log('Funding Broadcaster with 10 ETH...');
    await (await deployer.sendTransaction({ to: broadcaster.address, value: ethers.utils.parseEther('10') })).wait();
  }

  // ========== Reset chain state ==========
  console.log('--- Resetting chain state (debugResetBenchState) ---\n');
  const resetStart = Date.now();

  const resetTx = await railgun.connect(deployer).debugResetBenchState(
    nullifiers,
    rootIndex,
    root,
  );
  const resetReceipt = await resetTx.wait();
  const resetMs = Date.now() - resetStart;
  console.log(`  Reset complete: ${resetMs}ms, gas: ${resetReceipt.gasUsed.toString()}`);
  console.log(`  Cleared ${nullifiers.length} nullifiers, restored root at index ${rootIndex}`);

  // ========== Deserialize proofs ==========
  console.log('\nDeserializing proofs...');
  const deserializeStart = Date.now();
  const allBatchTransactions: PublicInputs[][] = batches.map((batch: any) =>
    batch.transactions.map(deserializePublicInputs),
  );
  const allActionData = batches.map((batch: any) => batch.actionData);
  const deserializeMs = Date.now() - deserializeStart;
  console.log(`  ${config.totalTxs} proofs deserialized in ${deserializeMs}ms`);

  // ========== Submit relay batches ==========
  console.log('\n--- Submit Relay Calls ---\n');

  const submitStart = Date.now();
  const baseNonce = await broadcaster.getTransactionCount('pending');

  console.log(`Sending ${allBatchTransactions.length} relay calls...`);
  const txResponses = await Promise.all(
    allBatchTransactions.map(async (batchTxs, batchIdx) => {
      return relayAdapt.connect(broadcaster).relay(
        batchTxs,
        allActionData[batchIdx],
        { gasLimit: GAS_LIMIT_PER_RELAY, nonce: baseNonce + batchIdx },
      );
    }),
  );

  console.log('Waiting for confirmations...');
  const receipts = await Promise.all(txResponses.map((tx) => tx.wait()));
  const submitEnd = Date.now();

  // ========== Collect results ==========
  let totalGasUsed = ethers.BigNumber.from(0);
  let firstBlockNumber = Infinity;
  let lastBlockNumber = 0;
  let firstBlockTimestamp = Infinity;
  let lastBlockTimestamp = 0;

  for (let i = 0; i < receipts.length; i++) {
    const receipt = receipts[i];
    totalGasUsed = totalGasUsed.add(receipt.gasUsed);
    const block = await ethers.provider.getBlock(receipt.blockNumber);
    if (receipt.blockNumber < firstBlockNumber) {
      firstBlockNumber = receipt.blockNumber;
      firstBlockTimestamp = block.timestamp;
    }
    if (receipt.blockNumber > lastBlockNumber) {
      lastBlockNumber = receipt.blockNumber;
      lastBlockTimestamp = block.timestamp;
    }
    console.log(`  Relay ${i + 1}: block=${receipt.blockNumber} gas=${receipt.gasUsed.toString()}`);
  }

  // ========== Report ==========
  const actualTxCount = config.totalTxs;
  const submitDuration = (submitEnd - submitStart) / 1000;
  const onChainDuration = lastBlockTimestamp - firstBlockTimestamp;
  const e2eTps = actualTxCount / submitDuration;
  const onChainTps = onChainDuration > 0 ? actualTxCount / onChainDuration : actualTxCount;
  const avgGasPerTx = totalGasUsed.div(actualTxCount);

  console.log('\n============================================');
  console.log('  Benchmark Report');
  console.log('============================================');
  console.log('Config:');
  console.log(`  Wallets: ${config.wallets}`);
  console.log(`  Circuit: ${config.inputsPerTx}-in / ${config.outputsPerTx}-out`);
  console.log(`  Total Transactions: ${actualTxCount}`);
  console.log(`  TXs per Relay: ${config.txsPerRelay}`);
  console.log('');
  console.log('Setup (from bench-setup):');
  console.log(`  Shield Gas: ${setupStats.shieldGas}`);
  console.log(`  Notes Created: ${setupStats.notesCreated}`);
  console.log(`  Setup Duration: ${setupStats.durationMs}ms`);
  console.log('');
  console.log('Proof Generation (from bench-setup):');
  console.log(`  Total: ${proofStats.totalMs}ms`);
  console.log(`  Avg: ${proofStats.avgMs}ms`);
  console.log(`  Min: ${proofStats.minMs}ms | Max: ${proofStats.maxMs}ms`);
  console.log('');
  console.log('This Run:');
  console.log(`  Proof Load + Deserialize: ${loadMs + deserializeMs}ms`);
  console.log(`  Chain Reset: ${resetMs}ms (gas: ${resetReceipt.gasUsed.toString()})`);
  console.log('');
  console.log('On-chain Results:');
  console.log(`  Relay Calls: ${receipts.length}`);
  console.log(`  Total Gas: ${totalGasUsed.toString()}`);
  console.log(`  Avg Gas/Tx: ${avgGasPerTx.toString()}`);
  console.log(`  Blocks: ${firstBlockNumber} -> ${lastBlockNumber}`);
  console.log(`  On-chain Duration: ${onChainDuration}s`);
  console.log(`  On-chain TPS: ${onChainTps.toFixed(2)}`);
  console.log(`  E2E Submit Duration: ${submitDuration.toFixed(2)}s`);
  console.log(`  E2E TPS: ${e2eTps.toFixed(2)}`);
  console.log('============================================');

  // Write transaction hashes to temp file (appended to result file by 2-bench.sh)
  const hashLines = [
    '',
    'Transaction Hashes:',
    ...receipts.map((r, i) => `  Relay ${i + 1}: ${r.transactionHash}`),
    '',
  ].join('\n');
  fs.writeFileSync(path.join(__dirname, '../.bench-hashes.tmp'), hashLines);
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
